style.css:
@-moz-document url("https://office.webullbroker.com/teamup/develop-management/jenkins/plan") {
.ant-drawer-content-wrapper{
    width:100% !important;
}
.ant-drawer .ant-drawer-content-wrapper .background-grid-app{
  width:40% !important;
  height:97% !important;
  float:left;
border-radius: 38px;
background: #ffffff;
box-shadow:  9px 9px 18px #666666,
             -9px -9px 18px #ffffff;
  margin-top:1%;
  margin-right:0.5%;
}
.ant-drawer .plan-template-drawer .ant-drawer-header{
  box-shadow: -2px -4px 18px #666666;
}

.ant-drawer .ant-pro-table {
  height:97% !important
}

.ant-drawer .ant-pro-table .ant-pro-card{
    width:59.5% !important;
  	height:100% !important;
border-radius: 38px;
background: #ffffff;
box-shadow:  9px 9px 18px #666666,
             -9px -9px 18px #ffffff;
  margin-top:1%;
}

.ant-drawer-header{
  z-index:2
}
.ant-table-cell .ant-space {
  display:block
}
.x6-graph{
    width:100% !important;
  	height:100% !important;
  border-radius: 38px !important;
background: #ffffff !important;
box-shadow:  9px 9px 18px #666666,
             -9px -9px 18px #ffffff !important;
  margin:0 !important;
  padding:0 !important
}
.x6-graph-svg{
      border-radius: 50px;
}
.ant-drawer .ant-drawer-content-wrapper .ant-drawer-body{
  overflow:hidden;
}
.ant-spin-container{
     height: 100% !important;
}

.ant-table-wrapper, .ant-spin-nested-loading{
     height: 95% !important;
}

.ant-table.ant-table-middle{
   height: 100% !important;
    overflow-y: scroll;
}

.ant-drawer-body .ant-row.sticky-top{
  position:fixed;
  top:15px;
  z-index:2;
  margin-left:30%;
  background-color:unset
}

.ant-space-item a{
  padding:5px !important;
  margin:1px 5px !important;
}

.ant-space-item .ant-btn{
  padding:5px !important;
  margin: 1px 5px !important;
}

.ant-table-wrapper .ant-table-pagination.ant-pagination{
  margin:0 !important;
}
/* 缩放动画*/
.x6-graph-svg-viewport{
   	transition: all 0.1s;
}
}
